/* DOM controls and accessible narration for the WebGL classroom. */
let cinemaMode=true,cinemaIndex=0,cinemaLesson=null,cinemaFullTrace=false,cinemaSpeed=2400,cinemaTimer=null,cinemaPlaying=false,cinemaRenderer=null,cinemaGeneration=0,cinemaEnginePromise=null;
function disposeCinema(){cinemaGeneration++;clearInterval(cinemaTimer);cinemaTimer=null;cinemaPlaying=false;cinemaRenderer?.dispose();cinemaRenderer=null;}
function cinemaSteps(p){let values=CinemaModel.frames(p,!cinemaFullTrace);if(!cinemaFullTrace&&values.length>60){const selected=new Set([...values.slice(0,4),...values.slice(-4)]);for(let i=1;i<53;i++)selected.add(values[Math.round(i*(values.length-1)/53)]);values=[...selected].sort((a,b)=>a-b);}return values;}
function cinemaPanel(p){if(cinemaLesson!==p.id){cinemaLesson=p.id;cinemaIndex=0;}const steps=cinemaSteps(p);cinemaIndex=Math.min(cinemaIndex,steps.length-1);const f=CinemaModel.frame(p,steps[cinemaIndex]);return `<section class="classroom" aria-label="3D algorithm classroom"><div class="classroom-bar"><div><span class="classroom-dot"></span> INTERACTIVE CLASSROOM <span class="classroom-version">3D</span></div><button class="classroom-link" data-cinema="legacy">Open earlier 2D walkthrough ${icon('arrow')}</button></div><div class="cinema-stage"><div id="cinema-canvas"></div><div class="cinema-scene-label"><span id="cinema-kind">${esc(f.representation)}</span><small id="cinema-trace-step">TRACE ${f.index+1} / ${f.total}</small></div><div class="cinema-code" id="cinema-code">${cinemaCode(p,f)}</div><div class="cinema-loading" id="cinema-loading">Setting up the 3D classroom…</div><div class="cinema-camera" aria-label="Camera controls"><button data-camera="angle" title="Perspective view">3D</button><button data-camera="top" title="Top view">Top</button><button data-camera="front" title="Front view">Front</button><button data-camera="reset" title="Reset camera">${icon('reset')}</button><span>Drag to orbit · scroll to zoom</span></div><div class="cinema-legend"><span><i class="key-current"></i> Current</span><span><i class="key-resolved"></i> Reused / changed</span><span><i class="key-input"></i> Input</span><span><i class="key-memory"></i> Memory</span></div></div><div class="cinema-transport"><button data-cinema="reset" aria-label="Restart 3D lesson">${icon('reset')}</button><button data-cinema="prev" aria-label="Previous 3D scene">${icon('prev')}</button><button data-cinema="play" class="cinema-play">${icon('play')} Play lesson</button><button data-cinema="next" aria-label="Next 3D scene">${icon('next')}</button><span id="cinema-position">${cinemaIndex+1} / ${steps.length}</span><select id="cinema-speed" aria-label="3D playback speed">${[[4000,'Slow'],[2400,'Normal'],[1100,'Fast']].map(([v,t])=>`<option value="${v}" ${v===cinemaSpeed?'selected':''}>${t}</option>`).join('')}</select><label class="cinema-detail"><input id="cinema-detail" type="checkbox" ${cinemaFullTrace?'checked':''}> Every Python step</label></div><div class="cinema-timeline"><input id="cinema-scrub" aria-label="3D scene position" type="range" min="0" max="${steps.length-1}" value="${cinemaIndex}"><div><button data-chapter="0">01 &nbsp; Set up</button><button data-chapter="0.5">02 &nbsp; Work through</button><button data-chapter="1">03 &nbsp; See the result</button></div></div><div id="cinema-narrative">${cinemaNarrative(p,f)}</div><details class="cinema-accessible"><summary>Read the scene as text</summary><div id="cinema-text">${cinemaText(f)}</div></details></section>`;}
function cinemaCode(p,f){return `<div class="cinema-code-heading"><span>PYTHON ${p.track==='dp'?'TRANSITION':'IN ACTION'}</span><span>${p.track==='dp'?'Memoization':'L'+f.line}</span></div><p>${p.track==='dp'?'Combine already-solved dependencies':f.final?'Final recorded step':'The highlighted line is about to run'}</p><pre>${f.code.split('\n').map((s,i)=>`<span class="${p.track==='dp'||i+f.codeStart===f.line?'current-line':''}"><small>${p.track==='dp'?'':i+f.codeStart}</small><code>${highlight(s||' ')}</code></span>`).join('')}</pre><div class="cinema-callstack">${f.stack.map(s=>`<span>${esc(s)}</span>`).join('<i>›</i>')}</div>`;}
function cinemaNarrative(p,f){return `<div class="cinema-explanation"><div class="cinema-explanation-main"><span class="cinema-eyebrow">${f.final?'THE RESULT':'WHAT IS HAPPENING'}</span><h2>${esc(f.title)}</h2><p>${esc(f.explanation)}</p>${f.final?`<div class="cinema-result">Example answer <strong>${esc(CinemaModel.compact(f.result))}</strong></div>`:''}</div><div class="cinema-why"><span class="cinema-eyebrow">THE IDEA BEHIND THE PICTURE</span><p>${esc(f.rule)}</p></div></div><div class="cinema-metrics">${f.metrics.map(m=>`<div><span>${esc(m.key)}</span><strong>${esc(m.value)}</strong></div>`).join('')}</div><p class="cinema-footnote">${cinemaFullTrace?'Every recorded step.':'Selected state changes; trace numbers identify any skipped checkpoints.'} ${f.notes.map(esc).join(' ')}</p>`;}
function cinemaText(f){return `<ul>${f.objects.map(o=>`<li>${esc(o.label||o.id)}: ${esc(o.value)} (${esc(o.role)})</li>`).join('')}</ul>`;}
function bindCinema(p){
 if(!cinemaMode){document.querySelector('[data-cinema="open"]')?.addEventListener('click',()=>{stop();cinemaMode=true;render();});return false;}
 if(!document.querySelector('#cinema-canvas'))return false;
 let steps=cinemaSteps(p);const host=document.querySelector('#cinema-canvas'),generation=cinemaGeneration;
 const update=()=>{cinemaIndex=Math.max(0,Math.min(cinemaIndex,steps.length-1));const f=CinemaModel.frame(p,steps[cinemaIndex]);$('#cinema-code').innerHTML=cinemaCode(p,f);$('#cinema-narrative').innerHTML=cinemaNarrative(p,f);$('#cinema-text').innerHTML=cinemaText(f);$('#cinema-kind').textContent=f.representation;$('#cinema-trace-step').textContent=`TRACE ${f.index+1} / ${f.total}`;$('#cinema-position').textContent=`${cinemaIndex+1} / ${steps.length}`;$('#cinema-scrub').value=cinemaIndex;$('[data-cinema="play"]').innerHTML=icon(cinemaPlaying?'pause':'play')+(cinemaPlaying?' Pause':' Play lesson');$('[data-cinema="prev"]').disabled=cinemaIndex===0;$('[data-cinema="next"]').disabled=cinemaIndex===steps.length-1;cinemaRenderer?.setFrame(f);};
 const pause=()=>{clearInterval(cinemaTimer);cinemaTimer=null;cinemaPlaying=false;};const move=i=>{pause();cinemaIndex=i;update();};const play=()=>{cinemaPlaying=true;clearInterval(cinemaTimer);cinemaTimer=setInterval(()=>{if(!host.isConnected){pause();return;}cinemaIndex++;if(cinemaIndex>=steps.length-1){cinemaIndex=steps.length-1;pause();}update();},cinemaSpeed);update();};
 document.querySelectorAll('[data-cinema]').forEach(b=>b.onclick=()=>{const action=b.dataset.cinema;if(action==='legacy'){pause();cinemaMode=false;render();}if(action==='prev')move(cinemaIndex-1);if(action==='next')move(cinemaIndex+1);if(action==='reset')move(0);if(action==='play'){if(cinemaPlaying){pause();update();}else{if(cinemaIndex===steps.length-1)cinemaIndex=0;play();}}});
 document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>cinemaRenderer?.view(b.dataset.camera));document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>move(Math.round(+b.dataset.chapter*(steps.length-1))));$('#cinema-scrub').oninput=e=>move(+e.target.value);$('#cinema-speed').onchange=e=>{cinemaSpeed=+e.target.value;if(cinemaPlaying)play();};$('#cinema-detail').onchange=e=>{const actual=steps[cinemaIndex];pause();cinemaFullTrace=e.target.checked;steps=cinemaSteps(p);cinemaIndex=Math.max(0,steps.findIndex(i=>i>=actual));$('#cinema-scrub').max=steps.length-1;update();};
 update();
 cinemaEnginePromise??=import('./cinema-renderer.mjs');cinemaEnginePromise.then(({ClassroomRenderer})=>{if(generation!==cinemaGeneration||!host.isConnected)return;try{cinemaRenderer=new ClassroomRenderer(host);cinemaRenderer.setFrame(CinemaModel.frame(p,steps[cinemaIndex]));$('#cinema-loading').hidden=true;}catch(error){$('#cinema-loading').textContent='3D is unavailable on this device. The code, explanations, and text scene still work.';document.querySelector('.cinema-accessible').open=true;}}).catch(()=>{if(host.isConnected)$('#cinema-loading').textContent='The 3D engine could not load. You can still follow the code and text scene below.';});
 return true;
}
